${pagingTop}
SELECT
	homepage_id, quiz_idx, quiz_type, quiz_name, quiz_year, quiz_month, book_name, book_author, book_publisher,
	call_no, book_desc, quiz_start_date, quiz_end_date, book_image,
	top_html, bottom_html, delete_yn, add_date, add_id, modify_date, modify_id, applicant_id_yn, address_yn,
	(SELECT COUNT(*) FROM QUIZ_REQ WHERE homepage_id = a.homepage_id AND quiz_idx = a.quiz_idx) AS quiz_req_count,
	select_cnt, re_select_cnt,family_yn
FROM
	QUIZ a
WHERE
	homepage_id = #{homepage_id}
AND	delete_yn = 'N'

AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	quiz_type = #{quiz_type}


AND	quiz_year = #{quiz_year}


AND quiz_month = #{quiz_month}

ORDER BY quiz_idx DESC
${pagingBottom}

